<?php get_header();while(have_posts()):the_post();$id=get_the_ID(); ?>
<article><div class="hero"><?php the_post_thumbnail('full',['class'=>'wp-hero-photo','fetchpriority'=>'high']); ?><a class="trip-back" href="<?php echo esc_url(home_url('/explore/')); ?>">← Back to places</a><p class="eyebrow"><?php echo esc_html(gj_value('address')); ?></p><h1><?php the_title(); ?></h1></div>
<div class="body wp-guide wp-content"><div class="trip-summary"><?php the_content(); ?><a class="action" href="<?php echo esc_url('https://www.google.com/maps/search/?api=1&query='.rawurlencode(gj_value('address',null,get_the_title()))); ?>" target="_blank" rel="noopener">Get directions ↗</a></div>
<?php $facts=gj_value('facts',null,[]);if($facts): ?><dl class="trip-facts"><?php foreach($facts as$f): ?><div><dt><?php echo esc_html($f['fact_label']); ?></dt><dd><?php echo esc_html($f['fact_value']); ?></dd><dd><?php echo esc_html($f['fact_note']); ?></dd></div><?php endforeach; ?></dl><?php endif; ?>
<nav class="trip-jumps" aria-label="On this page"><a href="#things">Things to do</a><a href="#visit">Plan your visit</a><a href="#getting">Getting there</a><a href="#day">Day plan</a></nav>
<?php $gallery=gj_value('gallery',null,[]);if($gallery): ?><section class="wp-gallery" aria-label="Destination photos"><?php foreach($gallery as$photo): ?><figure><?php echo wp_get_attachment_image($photo,'large',false,['loading'=>'lazy']);gj_photo_credit($photo); ?></figure><?php endforeach; ?></section><?php endif; ?>
<section class="wp-section" id="things"><h2>Things to do</h2><?php foreach(gj_value('stops',null,[])as$stop): ?><div><h3><?php echo esc_html($stop['stop_title']); ?></h3><p><?php echo esc_html($stop['stop_description']); ?></p><?php if($stop['stop_image']): ?><figure><?php echo wp_get_attachment_image($stop['stop_image'],'large');gj_photo_credit($stop['stop_image']); ?></figure><?php endif;if($stop['stop_map']): ?><a href="<?php echo esc_url('https://www.google.com/maps/search/?api=1&query='.rawurlencode($stop['stop_map'])); ?>" target="_blank" rel="noopener">View on map ↗</a><?php endif;if(!empty($stop['stop_destination'])&&get_post_status($stop['stop_destination'])==='publish'): ?><a href="<?php echo esc_url(get_permalink($stop['stop_destination'])); ?>">Read destination guide</a><?php endif; ?></div><?php endforeach; ?></section>
<?php if(gj_value('history')): ?><section class="wp-section"><h2>History</h2><?php echo wp_kses_post(gj_value('history')); ?></section><?php endif; ?>
<section class="wp-section" id="visit"><h2>Plan your visit</h2><?php echo wp_kses_post(gj_value('visit_notes')); ?><p><?php echo esc_html(gj_value('facilities')); ?></p></section>
<section class="wp-section" id="getting"><h2>Getting there</h2><h3>By bus</h3><p><?php echo esc_html(gj_value('bus')); ?></p><h3>By car or taxi</h3><p><?php echo esc_html(gj_value('car')); ?></p></section>
<?php $venues=gj_value('dining_stays',null,[]);if($venues): ?><section class="wp-section"><h2>Eat and stay</h2><?php foreach($venues as$v): ?><h3><?php echo esc_html($v['venue_title']); ?></h3><p><?php echo esc_html($v['venue_description']); ?></p><?php if($v['venue_url']): ?><a href="<?php echo esc_url($v['venue_url']); ?>" rel="noopener">Visit website ↗</a><?php endif;endforeach; ?></section><?php endif; ?>
<section class="wp-section" id="day"><h2>Make a day of it</h2><ol><?php foreach(gj_value('day_plan',null,[])as$stage): ?><li><h3><?php echo esc_html($stage['stage_title']); ?></h3><p><?php echo esc_html($stage['stage_description']); ?></p></li><?php endforeach; ?></ol></section>
<?php $sources=gj_value('sources',null,[]);if($sources): ?><section class="wp-section"><h2>Sources</h2><ul><?php foreach($sources as$s): ?><li><a href="<?php echo esc_url($s['source_url']); ?>" rel="noopener"><?php echo esc_html($s['source_title']); ?></a></li><?php endforeach; ?></ul><?php if(gj_value('verification_date')): ?><p>Last verified: <?php echo esc_html(gj_value('verification_date')); ?></p><?php endif; ?></section><?php endif; ?>
<section class="wp-section"><h2>More places to explore</h2><?php $related=gj_value('related',null,[]);$args=['posts_per_page'=>3,'post__not_in'=>[$id]];if($related){$args['post__in']=$related;$args['orderby']='post__in';}else{$terms=wp_get_post_terms($id,'outing',['fields'=>'ids']);if($terms)$args['tax_query']=[['taxonomy'=>'outing','terms'=>$terms]];}gj_cards($args); ?></section>
</div></article><?php endwhile;get_footer(); ?>
